questionvariables.text:
/* Randomize probabilities using integer math first to prevent floating point inaccuracies */
p0_v : rand([5, 10, 15]);
p1_v : rand([20, 25, 30, 35]);
p3_v : rand([15, 20, 25]);
p4_v : rand([5, 10]);

/* Reverse engineer the missing value so the sum is exactly 100 */
p2_v : 100 - (p0_v + p1_v + p3_v + p4_v);

/* Convert to exact fractions/decimals for display and evaluation */
p0 : p0_v / 100;
p1 : p1_v / 100;
p2 : p2_v / 100;
p3 : p3_v / 100;
p4 : p4_v / 100;

/* Target answers */
ta1 : p2;
ta2 : p2 + p3 + p4;

/* Distractor variable for PRT check */
ta2_wrong : p3 + p4;
